gGE(){return"\u041d\u0430\u0434\u0441\u0438\u043b\u0430\u0454\u043c\u043e \u0437\u043c\u0456\u043d\u0438\u2026"},
gGD(){return"\u041d\u0435\u043c\u0430\u0454 \u0437\u0432\u2019\u044f\u0437\u043a\u0443 \u0437 \u0441\u0435\u0440\u0432\u0435\u0440\u043e\u043c. \u0417\u043c\u0456\u043d\u0438 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043e \u043d\u0430 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457 \u2014 \u0432\u043e\u043d\u0438 \u043d\u0430\u0434\u0456\u0448\u043b\u044e\u0442\u044c\u0441\u044f \u0441\u0430\u043c\u0456, \u0449\u043e\u0439\u043d\u043e \u0437\u2019\u044f\u0432\u0438\u0442\u044c\u0441\u044f \u0437\u0432\u2019\u044f\u0437\u043e\u043a."},
gwl(){return"\u0421\u0435\u0440\u0432\u0435\u0440 \u0441\u0438\u043d\u0445\u0440\u043e\u043d\u0456\u0437\u0430\u0446\u0456\u0457 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0438\u0439. \u0421\u043f\u0438\u0441\u043a\u0438 \u043d\u0430 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457 \u0432 \u043f\u043e\u0440\u044f\u0434\u043a\u0443 \u2014 \u0441\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435, \u043a\u043e\u043b\u0438 \u0437\u2019\u044f\u0432\u0438\u0442\u044c\u0441\u044f \u0437\u0432\u2019\u044f\u0437\u043e\u043a."},
gME(){return"\u0412\u0438\u0439\u0442\u0438 \u0437\u0456 \u0441\u043f\u0438\u0441\u043a\u0443"},
gL2(){return"\u0412\u0438\u0434\u0430\u043b\u0438\u0442\u0438 \u0432 \u0443\u0441\u0456\u0445"},
MF(a,b){return"\xab"+a+"\xbb \u2014 \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0441\u043f\u0438\u0441\u043e\u043a, \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432: "+b+". \u0412\u0438\u0439\u0434\u0456\u0442\u044c \u2014 \u0432 \u0456\u043d\u0448\u0438\u0445 \u0432\u0456\u043d \u0437\u0430\u043b\u0438\u0448\u0438\u0442\u044c\u0441\u044f. \u0410\u0431\u043e \u0432\u0438\u0434\u0430\u043b\u0456\u0442\u044c \u0432 \u0443\u0441\u0456\u0445."},
MH(a){return"\u0412\u0438 \u0432\u0438\u0439\u0448\u043b\u0438 \u0437 \xab"+a+"\xbb"},
gMG(){return"\u0412\u0438\u0439\u0442\u0438 \u043f\u043e\u043a\u0438 \u043d\u0435 \u043c\u043e\u0436\u043d\u0430: \u0441\u0435\u0440\u0432\u0435\u0440 \u0449\u0435 \u043d\u0435 \u043e\u043d\u043e\u0432\u043b\u0435\u043d\u043e. \u0421\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u043f\u0456\u0437\u043d\u0456\u0448\u0435."},
gDR(){return"\u0417\u0430\u043f\u0440\u043e\u0441\u0438\u0442\u0438 \u0434\u043e \u0441\u043f\u0438\u0441\u043a\u0443"},
gNX(){return"\u042f\u043a\u0438\u043c \u0441\u043f\u0438\u0441\u043a\u043e\u043c \u043f\u043e\u0434\u0456\u043b\u0438\u0442\u0438\u0441\u044f?"},
